using Auth0.AspNetCore.Authentication;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddAuth0WebAppAuthentication(options =>
{
    options.Domain = builder.Configuration["Auth0:Domain"]!;
    options.ClientId = builder.Configuration["Auth0:ClientId"]!;
    options.ClientSecret = builder.Configuration["Auth0:ClientSecret"]!;

    options.CallbackPath = new PathString("/callback");
    options.LogoutPath = new PathString("/logout");
});

builder.Services.AddAuthorization();

var app = builder.Build();

app.UseHttpsRedirection();
app.UseStaticFiles();
app.UseRouting();

app.UseAuthentication();
app.UseAuthorization();

app.MapGet("/", async context =>
{
    if (!context.User.Identity?.IsAuthenticated == true)
    {
        var redirect = context.Request.GetEncodedPathAndQuery();
        context.ChallengeAsync("Auth0", new AuthenticationProperties
        {
            RedirectUri = redirect
        });
        return;
    }
    await context.Response.WriteAsync($"Hello, {context.User.Identity.Name}!");
});

app.MapGet("/logout", async context =>
{
    await context.SignOutAsync("Auth0", new AuthenticationProperties
    {
        RedirectUri = "/"
    });
});

app.Run();

exports.onExecutePostLogin = async (event) => {
  if (event.authorization) {
    // Add user metadata to ID token
    event.idToken.setCustomClaim(
      'https://app.example.com/roles',
      event.user.user_metadata?.roles || []
    );

    // Add tenant info for multi-tenant apps
    event.idToken.setCustomClaim(
      'tenant_id',
      event.user.user_metadata?.tenant_id
    );

    // Log for debugging
    console.log('User logged in:', event.user.email);
    console.log('Client:', event.client.name);
  }
};

// C# Example with Modern Patterns
using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace Example
{
    // Generic repository interface
    public interface IRepository<T> where T : class
    {
        Task<T?> GetByIdAsync(int id);
        Task<IEnumerable<T>> GetAllAsync();
        Task<T> CreateAsync(T entity);
        Task UpdateAsync(T entity);
        Task DeleteAsync(int id);
    }

    // Service with dependency injection
    public class UserService
    {
        private readonly IRepository<User> _repository;
        private readonly ILogger<UserService> _logger;

        public UserService(
            IRepository<User> repository,
            ILogger<UserService> logger)
        {
            _repository = repository;
            _logger = logger;
        }

        public async Task<User?> GetUserWithOrdersAsync(int userId)
        {
            try
            {
                _logger.LogInformation("Fetching user {UserId}", userId);
                var user = await _repository.GetByIdAsync(userId);

                if (user == null)
                {
                    _logger.LogWarning("User {UserId} not found", userId);
                    return null;
                }

                return user;
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching user {UserId}", userId);
                throw;
            }
        }
    }
}

